SELECT '==1. PARA TODOS LOS ITEMS DELETED, BUSCAR ULTIMO FINALGRADE NO-NULL POR USER ==' as '';
SELECT t.itemid, t.userid, u.firstname, u.lastname, t.finalgrade, t.dt FROM (SELECT gh.itemid, gh.userid, gh.finalgrade, from_unixtime(gh.timemodified) dt, ROW_NUMBER() OVER (PARTITION BY gh.itemid, gh.userid ORDER BY gh.timemodified DESC) AS rn FROM isi_grade_grades_history gh WHERE gh.itemid IN (SELECT id FROM isi_grade_items WHERE courseid = 74 AND itemmodule IN ('assign','quiz')) AND gh.finalgrade IS NOT NULL AND gh.finalgrade >= 0) t JOIN isi_user u ON u.id = t.userid WHERE t.rn = 1 ORDER BY t.itemid, t.userid;
